use vstd::prelude::*;

verus! {

    // A simple enum to tag a vector as either a row‐vector or a column‐vector.
    pub enum ExpandedVector<T> {
        RowVector(Vec<T>),
        ColumnVector(Vec<T>),
    }

    // expand_dims takes ownership of vector `a` and an axis indicator.
    //
    // Requires:
    //   1. axis ≤ 1  (since only 0 or 1 are valid)
    //
    // Ensures:
    //   - If axis == 0, the result is RowVector(a).
    //   - If axis == 1, the result is ColumnVector(a).
    fn expand_dims<T>(a: Vec<T>, axis: usize) -> ExpandedVector<T>
        requires
            axis <= 1,
        ensures
            // if axis == 0 then result must be RowVector containing exactly `a`
            axis == 0 ==>
                match result {
                    ExpandedVector::RowVector(ref vec) => vec == &a,
                    _ => false
                },
        ensures
            // if axis == 1 then result must be ColumnVector containing exactly `a`
            axis == 1 ==>
                match result {
                    ExpandedVector::ColumnVector(ref vec) => vec == &a,
                    _ => false
                },
    {
        if axis == 0 {
            // axis == 0 case: wrap as a row
            ExpandedVector::RowVector(a)
        } else {
            // by the requires, axis ≤ 1, so here axis must be 1
            assert(axis == 1);
            ExpandedVector::ColumnVector(a)
        }
    }

}

